verify_msg(Msg, MsgName) when is_atom(MsgName) -> verify_msg(Msg, MsgName, []).

verify_msg(Msg, MsgName, Opts) ->
    TrUserData = proplists:get_value(user_data, Opts),
    case MsgName of
        register_request -> v_msg_register_request(Msg, [MsgName], TrUserData);
        register_response -> v_msg_register_response(Msg, [MsgName], TrUserData);
        get_account_request -> v_msg_get_account_request(Msg, [MsgName], TrUserData);
        get_account_response -> v_msg_get_account_response(Msg, [MsgName], TrUserData);
        request_email_verification_request -> v_msg_request_email_verification_request(Msg, [MsgName], TrUserData);
        request_email_verification_response -> v_msg_request_email_verification_response(Msg, [MsgName], TrUserData);
        confirm_email_verification_request -> v_msg_confirm_email_verification_request(Msg, [MsgName], TrUserData);
        confirm_email_verification_response -> v_msg_confirm_email_verification_response(Msg, [MsgName], TrUserData);
        request_password_reset_request -> v_msg_request_password_reset_request(Msg, [MsgName], TrUserData);
        request_password_reset_response -> v_msg_request_password_reset_response(Msg, [MsgName], TrUserData);
        confirm_password_reset_request -> v_msg_confirm_password_reset_request(Msg, [MsgName], TrUserData);
        confirm_password_reset_response -> v_msg_confirm_password_reset_response(Msg, [MsgName], TrUserData);
        request_email_change_request -> v_msg_request_email_change_request(Msg, [MsgName], TrUserData);
        request_email_change_response -> v_msg_request_email_change_response(Msg, [MsgName], TrUserData);
        confirm_email_change_request -> v_msg_confirm_email_change_request(Msg, [MsgName], TrUserData);
        confirm_email_change_response -> v_msg_confirm_email_change_response(Msg, [MsgName], TrUserData);
        login_request -> v_msg_login_request(Msg, [MsgName], TrUserData);
        login_response -> v_msg_login_response(Msg, [MsgName], TrUserData);
        validate_token_request -> v_msg_validate_token_request(Msg, [MsgName], TrUserData);
        validate_token_response -> v_msg_validate_token_response(Msg, [MsgName], TrUserData);
        validate_session_request -> v_msg_validate_session_request(Msg, [MsgName], TrUserData);
        validate_session_response -> v_msg_validate_session_response(Msg, [MsgName], TrUserData);
        refresh_token_request -> v_msg_refresh_token_request(Msg, [MsgName], TrUserData);
        refresh_token_response -> v_msg_refresh_token_response(Msg, [MsgName], TrUserData);
        logout_request -> v_msg_logout_request(Msg, [MsgName], TrUserData);
        logout_response -> v_msg_logout_response(Msg, [MsgName], TrUserData);
        revoke_all_sessions_request -> v_msg_revoke_all_sessions_request(Msg, [MsgName], TrUserData);
        revoke_all_sessions_response -> v_msg_revoke_all_sessions_response(Msg, [MsgName], TrUserData);
        get_user_request -> v_msg_get_user_request(Msg, [MsgName], TrUserData);
        get_user_response -> v_msg_get_user_response(Msg, [MsgName], TrUserData);
        search_users_request -> v_msg_search_users_request(Msg, [MsgName], TrUserData);
        search_users_response -> v_msg_search_users_response(Msg, [MsgName], TrUserData);
        user_profile -> v_msg_user_profile(Msg, [MsgName], TrUserData);
        register_push_token_request -> v_msg_register_push_token_request(Msg, [MsgName], TrUserData);
        register_push_token_response -> v_msg_register_push_token_response(Msg, [MsgName], TrUserData);
        unregister_push_token_request -> v_msg_unregister_push_token_request(Msg, [MsgName], TrUserData);
        unregister_push_token_response -> v_msg_unregister_push_token_response(Msg, [MsgName], TrUserData);
        timestamp -> v_msg_timestamp(Msg, [MsgName], TrUserData);
        _ -> mk_type_error(not_a_known_message, Msg, [])
    end.


